import { RequestHandler, Router } from "express";
import { CatalogueService } from "../application/catalogue-service";
import { PlaceOrderInput } from "../application/dtos";
import { OrderService } from "../application/order-service";
import { DomainError } from "../domain/errors";
import { orderStatuses, OrderStatus } from "../domain/order-status";

const asyncRoute = (handler: RequestHandler): RequestHandler => (request, response, next) => {
  try { handler(request, response, next); } catch (error) { next(error); }
};

const isOrderStatus = (value: string): value is OrderStatus => orderStatuses.includes(value as OrderStatus);
const singleValue = (value: string | string[] | undefined, name: string): string => {
  if (typeof value !== "string") throw new DomainError(`${name} is required`);
  return value;
};

export class OrderController {
  public constructor(private readonly orders: OrderService, private readonly catalogue: CatalogueService) {}

  public router(): Router {
    const router = Router();
    router.post("/products", asyncRoute((req, res) => res.status(201).json(this.catalogue.create(req.body))));
    router.get("/products", asyncRoute((_req, res) => res.json(this.catalogue.listStock())));
    router.post("/orders", asyncRoute((req, res) => res.status(201).json(this.orders.place(req.body as PlaceOrderInput))));
    router.get("/orders", asyncRoute((req, res) => {
      const status = req.query.status;
      if (typeof status !== "string" || !isOrderStatus(status)) throw new DomainError("A valid status query parameter is required");
      res.json(this.orders.listByStatus(status));
    }));
    router.patch("/orders/:id/status", asyncRoute((req, res) => {
      const status = req.body?.status;
      if (typeof status !== "string" || !isOrderStatus(status)) throw new DomainError("A valid status is required");
      res.json(this.orders.advance(singleValue(req.params.id, "Order id"), status));
    }));
    router.post("/orders/:id/cancel", asyncRoute((req, res) => res.json(this.orders.cancel(singleValue(req.params.id, "Order id")))));
    return router;
  }
}

